-- G19: auditable reuse decision before generation.
create table public.content_contract_profiles(text_version_id uuid primary key references public.text_versions(id) on delete cascade,taxonomy_release_id uuid not null references public.taxonomy_releases(id) on delete restrict,lexical_release_id uuid not null references public.lexical_releases(id) on delete restrict,qa_status text not null check(qa_status in('pending','passed','failed')),predicted_success numeric not null check(predicted_success between 0 and 1),known_vocabulary_coverage numeric not null check(known_vocabulary_coverage between 0 and 1),word_count integer not null check(word_count>0),competency_ids uuid[] not null default '{}',construction_ids uuid[] not null default '{}',tense_keys text[] not null default '{}',concept_ids uuid[] not null default '{}',risk_class text not null check(risk_class in('low','medium','high')),source_verified boolean not null default false,profile_payload jsonb not null,updated_at timestamptz not null default now());
create table public.contract_reuse_decisions(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.generation_contracts(id) on delete restrict,student_id uuid not null references public.students(id) on delete cascade,decision text not null check(decision in('reuse','generate')),selected_text_version_id uuid references public.text_versions(id) on delete restrict,score numeric check(score between 0 and 1),ranked_candidates jsonb not null,excluded_candidates jsonb not null,explanation jsonb not null,matcher_version text not null,latency_ms integer not null check(latency_ms>=0),created_at timestamptz not null default now(),check((decision='reuse')=(selected_text_version_id is not null)));
create unique index reuse_decision_once_idx on public.contract_reuse_decisions(contract_id,matcher_version);create index content_contract_eligibility_idx on public.content_contract_profiles(taxonomy_release_id,lexical_release_id,qa_status,predicted_success);
alter table public.content_contract_profiles enable row level security;alter table public.contract_reuse_decisions enable row level security;create policy reusable_profile_read on public.content_contract_profiles for select using(qa_status='passed');create policy reuse_decision_read on public.contract_reuse_decisions for select using(public.can_view_student(student_id));grant select on public.content_contract_profiles,public.contract_reuse_decisions to authenticated;
